package com.codepilot1c.core.edt.development;
import org.junit.Test;import static org.junit.Assert.*;import java.util.*;import com.google.gson.JsonParser;
public class NativeHostBatchPlanTest {
 @Test public void explicitStepsArePreservedWithTypedDefaults(){var value=JsonParser.parseString(NativeHostBatchPlan.payload(Map.of("steps",List.of(Map.of("code","result=1;","screenshot",true,"caption","Stage 1"))))).getAsJsonObject().getAsJsonArray("steps").get(0).getAsJsonObject();assertEquals("client",value.get("context").getAsString());assertTrue(value.get("screenshot").getAsBoolean());assertEquals("Stage 1",value.get("caption").getAsString());}
 @Test public void malformedOrUnboundedBatchesFailBeforeSubmission(){for(Object steps:List.of(List.of(),Collections.nCopies(17,Map.of("code","result=1;")),List.of(Map.of("code","x","context","background")),List.of(Map.of("code","x","screenshot","true")),List.of(Map.of("code","x","unknown",true)))){try{NativeHostBatchPlan.payload(Map.of("steps",steps));fail();}catch(IllegalArgumentException expected){}}}
 @Test public void oldComponentCannotExecuteScreenshotBatch(){var input=Map.<String,Object>of("steps",List.of(Map.of("code","x","screenshot",true)));try{NativeHostBatchPlan.requireCapabilities(input,Map.of());fail();}catch(IllegalStateException expected){}NativeHostBatchPlan.requireCapabilities(input,Map.of("native_features",List.of("screenshot_png")));NativeHostBatchPlan.requireCapabilities(Map.of("steps",List.of(Map.of("code","x"))),Map.of());}

 @Test public void controlDefaultsAndProjectionArePreserved(){var steps=JsonParser.parseString(NativeHostBatchPlan.payload(Map.of("steps",List.of(Map.of("code","x","kind","wait"),Map.of("code","x","kind","read","select",List.of("rows.0.Name")))))).getAsJsonObject().getAsJsonArray("steps");assertEquals(60000,steps.get(0).getAsJsonObject().get("timeout_ms").getAsInt());assertEquals(1000,steps.get(0).getAsJsonObject().get("interval_ms").getAsInt());assertEquals("rows.0.Name",steps.get(1).getAsJsonObject().getAsJsonArray("select").get(0).getAsString());}
 @Test public void controlsRequireNewTemplateButLegacyBatchDoesNot(){var input=Map.<String,Object>of("steps",List.of(Map.of("code","x","kind","wait")));try{NativeHostBatchPlan.requireCapabilities(input,Map.of());fail();}catch(IllegalStateException expected){}NativeHostBatchPlan.requireCapabilities(input,Map.of("host_features",List.of("batch_controls_v1")));}
 @Test public void invalidTimingAndSelectorsFailBeforeClaim(){for(var extra:List.of(Map.of("kind","wait","timeout_ms",999),Map.of("kind","wait","timeout_ms",300001),Map.of("kind","wait","timeout_ms",1000.1),Map.of("kind","wait","interval_ms","1000"),Map.of("timeout_ms",1000),Map.of("kind","read","select",List.of("x()")),Map.of("kind","read","select",List.of("x","x")),Map.of("kind","assert","select",List.of("x")),Map.of("kind","mystery"))){var step=new HashMap<String,Object>(extra);step.put("code","x");try{NativeHostBatchPlan.payload(Map.of("steps",List.of(step)));fail(step.toString());}catch(IllegalArgumentException expected){}}}
}
